<?php require_once '../includes/auth.php';require_once '../config/koneksi.php';$q=trim($_GET['q']??'');$like="%$q%";$st=$conn->prepare('SELECT * FROM guru WHERE nama_guru LIKE ? OR nip LIKE ? OR jabatan LIKE ? ORDER BY id_guru DESC');$st->bind_param('sss',$like,$like,$like);$st->execute();$data=$st->get_result();$page_title='Data Guru';$active='guru';$prefix='../';include '../includes/header.php';?>
<div class="page-heading"><div><h1>Data Guru</h1><p>Kelola identitas dan status tenaga pendidik sekolah.</p></div><a class="btn btn-primary" href="tambah.php"><i class="bi bi-plus-lg me-1"></i>Tambah Guru</a></div><div class="panel"><div class="panel-head"><div><strong>Daftar Tenaga Pendidik</strong><div class="text-secondary small mt-1"><?= $data->num_rows ?> data ditemukan</div></div><form class="d-flex gap-2 searchbox"><input name="q" class="form-control" value="<?= e($q) ?>" placeholder="Cari nama, NIP, jabatan..."><button class="btn btn-outline-primary"><i class="bi bi-search"></i></button></form></div><div class="table-responsive"><table class="table"><thead><tr><th>No</th><th>NIP</th><th>Nama Guru</th><th>JK</th><th>Jabatan</th><th>No. HP</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php $no=1;while($r=$data->fetch_assoc()):?><tr><td><?= $no++ ?></td><td><?= e($r['nip']?:'-') ?></td><td><strong><?= e($r['nama_guru']) ?></strong></td><td><?= $r['jenis_kelamin']==='L'?'Laki-laki':'Perempuan' ?></td><td><?= e($r['jabatan']?:'-') ?></td><td><?= e($r['no_hp']?:'-') ?></td><td><span class="badge <?= $r['status']==='aktif'?'text-bg-success':'text-bg-secondary' ?>"><?= e(ucfirst(str_replace('_',' ',$r['status']))) ?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?= $r['id_guru'] ?>"><i class="bi bi-pencil"></i></a> <a class="btn btn-sm btn-outline-danger" data-confirm="Hapus data guru ini?" href="hapus.php?id=<?= $r['id_guru'] ?>"><i class="bi bi-trash"></i></a></td></tr><?php endwhile;if(!$no):?><tr><td colspan="8" class="empty">Data guru tidak ditemukan.</td></tr><?php endif;?></tbody></table></div></div><?php include '../includes/footer.php';?>